# Initial strip x=0, y=tau, u=tau^2 gives q0 = du/dtau = 2tau, p0 = u0/q0 = tau/2.
TAUS = [-2.0, -0.5, 0.5, 1.0, 3.0]
S_VALS = [-0.4, 0.0, 0.3, 0.7]


def check_option(f):
    reasons = []
    for t in TAUS:
        x0, y0, u0 = f(t, 0.0)
        if not (close(x0, 0.0) and close(y0, t) and close(u0, t*t)):
            reasons.append("initial_curve")
            return False, reasons
        X = lambda z: f(t, z)[0]
        Y = lambda z: f(t, z)[1]
